/**
 * Run from the repository root, with the saved patched 0.99.2 package available:
 * node packages/agent-runtime/src/pi/fixtures/pi-0.99.2-compaction.generate.mjs
 *
 * Synthetic only: no credential store, real profile or network request is used.
 * The portable entry is generated by the old harness's compaction operation.
 * Native and malformed entries are written by that operation's before_compaction
 * hook with synthetic details, NOT captured from real provider responses.
 * Product settlement markers are synthetic inputs written through the old session API.
 */
import assert from "node:assert/strict";
import { copyFile, mkdtemp, readFile, realpath, rm, writeFile } from "node:fs/promises";
import { isAbsolute, join, relative, resolve } from "node:path";
import { pathToFileURL } from "node:url";

const workspace = await realpath(process.cwd());
const saved = await realpath(resolve(".bench-tmp/pi-migration-vc496/baseline/core"));
const inside = relative(workspace, saved);
assert(!inside.startsWith("..") && !isAbsolute(inside), "saved build must be in this workspace");
assert.equal(JSON.parse(await readFile(join(saved, "package.json"), "utf8")).version, "0.99.2");
const load = (path) => import(pathToFileURL(join(saved, path)).href);
const { JsonlSessionRepo } = await load("dist/harness/session/jsonl/repo.js");
const { NodeExecutionEnv } = await load("dist/harness/env/nodejs.js");
const { BACKGROUND_CONTEXT: context } = await load("dist/harness/context.js");
const { value } = await load("dist/harness/session/values.js");
const { buildSessionContext } = await load("dist/harness/session/context.js");
const { convertToLlm } = await load("dist/harness/messages.js");
const { createAgentHarness } = await load("dist/harness/runtime/harness.js");
const { createAssistantMessageEventStream, createModels, fauxProvider } = await load(
  "node_modules/@earendil-works/pi-ai/dist/index.js",
);

const timestamp = 1800000000000;
const usage = {
  input: 11,
  output: 7,
  cacheRead: 2,
  cacheWrite: 0,
  totalTokens: 20,
  cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
};
const retainedUser = {
  role: "user",
  content: "Retained tail: continue the saved task with héllo 日本語 🙂.",
  timestamp: timestamp + 2,
};
const summary = "Portable 0.99.2 summary: preserve the saved task.";
const nativeSummary = "Synthetic native 0.99.2 checkpoint: preserve the saved task.";
const destination = resolve("packages/agent-runtime/src/pi/fixtures");

for (const kind of ["portable", "native", "malformed"]) {
  const root = await mkdtemp(join(workspace, ".pi-0992-generate-"));
  const modelId = kind === "native" ? "claude-opus-4-6" : "claude-sonnet-4-5";
  const assistant = (text, at) => ({
    role: "assistant",
    content: [{ type: "text", text }],
    api: "anthropic-messages",
    provider: "anthropic",
    model: modelId,
    usage,
    stopReason: "stop",
    timestamp: at,
  });
  const retainedAssistant = assistant("Retained answer from 0.99.2.", timestamp + 3);
  const providerRequests = [];
  const faux = fauxProvider({
    api: "anthropic-messages",
    provider: "anthropic",
    models: [{ id: modelId, reasoning: true }],
  });
  const models = createModels();
  models.setProvider({
    ...faux.provider,
    streamSimple: (_model, request) => {
      providerRequests.push(structuredClone(request.messages));
      const reply = assistant(
        providerRequests.length === 1 && kind === "portable"
          ? summary
          : "Verified old-runtime continuation.",
        timestamp + 4,
      );
      const events = createAssistantMessageEventStream();
      queueMicrotask(() => {
        events.push({ type: "start", partial: reply });
        events.push({ type: "done", reason: "stop", message: reply });
        events.end(reply);
      });
      return events;
    },
  });
  const repo = new JsonlSessionRepo({
    fileSystem: new NodeExecutionEnv({ cwd: root }),
    sessionsRoot: join(root, "sessions"),
    now: () => timestamp,
  });
  let harness;
  try {
    const session = await repo.create({ cwd: "/workspace/vc496/compatibility" }, context);
    const main = await session.createBranch("main", null, context);
    await session.setValue(
      value("volli.identity.v1"),
      {
        volliSessionId: "compat-session",
        volliThreadId: "compat-thread",
        volliAttachmentId: "compat-attachment",
      },
      context,
    );
    await main.appendMessage(
      { role: "user", content: "Before Pi 1.0: héllo 日本語 🙂", timestamp },
      context,
    );
    const settlements = [];
    const appendMarkedAssistant = async (message, turnId) => {
      const entryId = await main.appendMessage(message, context);
      settlements.push({
        kind: "message-settled",
        turnId,
        message: {
          entryId,
          role: "assistant",
          text: message.content[0].text,
          model: { providerId: message.provider, modelId: message.model },
        },
      });
    };
    await appendMarkedAssistant(assistant("Saved by 0.99.2", timestamp + 1), "compat-old-turn");
    const side = await session.createBranch("side", await main.getTipId(context), context);
    await side.appendMessage({ role: "user", content: "Sibling branch only", timestamp }, context);
    await main.appendMessage(retainedUser, context);
    await appendMarkedAssistant(retainedAssistant, "compat-tail-turn");
    for (const settlement of settlements)
      await main.appendCustomEntry("volli.observation.v1", settlement, context);
    await session.setName(`Pi 0.99.2 ${kind} compaction fixture`, context);
    const oldHistory = convertToLlm(
      await buildSessionContext(
        await main.findEntries({ order: "oldestFirst" }, context),
        undefined,
        context,
      ),
    );

    ({ harness } = await createAgentHarness(
      {
        session,
        models,
        model: faux.getModel(),
        thinkingLevel: "off",
        systemPrompt: "Synthetic compatibility fixture.",
        compaction: { enabled: false, reserveTokens: 1024, keepRecentTokens: 20 },
      },
      context,
    ));
    const lane = await harness.lane("main", context);
    if (kind !== "portable") {
      harness.hooks.on("before_compaction", ({ preparation }) => ({
        compaction: {
          summary: kind === "native" ? nativeSummary : "Before the upgrade",
          retainedTail: preparation.retainedTail,
          tokensBefore: preparation.tokensBefore,
          details: {
            providerCompaction:
              kind === "native"
                ? {
                    kind: "anthropic-messages",
                    block: { type: "compaction", content: nativeSummary },
                    model: modelId,
                    compactedAt: timestamp,
                  }
                : { opaque: "compat-opaque" },
          },
        },
      }));
    }
    const result = await lane.compact(undefined, context);
    assert.equal(result.ok, true, JSON.stringify(result));
    assert.equal(result.value.compaction.status, "completed", JSON.stringify(result));
    const entries = await main.findEntries({ order: "oldestFirst" }, context);
    const compacted = entries.findLast((entry) => entry.type === "compaction");
    assert.deepEqual(compacted.retainedTail, [retainedUser, retainedAssistant]);
    assert.equal(
      compacted.summary,
      kind === "portable" ? summary : kind === "native" ? nativeSummary : "Before the upgrade",
    );
    assert.equal(compacted.fromHook, kind !== "portable");
    const expectedContext = convertToLlm(await buildSessionContext(entries, undefined, context));
    const stem = join(destination, `pi-0.99.2-${kind}-compaction`);
    // Capture the completed compaction BEFORE verifying a subsequent old-runtime turn.
    await copyFile(session.metadata.path, `${stem}.jsonl`);
    const continued = await lane.prompt("Verify old-runtime context.", undefined, context);
    assert.equal(continued.ok, true, JSON.stringify(continued));
    assert.equal(continued.value.status, "completed", JSON.stringify(continued));
    const oldRequest = providerRequests.at(-1).filter((message) => message.role !== "system");
    assert.deepEqual(oldRequest.slice(0, -1), expectedContext);
    const requestText = JSON.stringify(oldRequest);
    assert(!requestText.includes("Before Pi 1.0"));
    assert(!requestText.includes("Saved by 0.99.2"));
    assert(!requestText.includes("Sibling branch only"));
    // Valid fixtures' references are the actual old harness's provider context.
    // Malformed recovery instead uses the pre-compaction old session reader's history.
    const contextPath =
      kind === "malformed" ? `${stem}.history.context.json` : `${stem}.context.json`;
    await writeFile(
      contextPath,
      `${JSON.stringify(kind === "malformed" ? oldHistory : oldRequest.slice(0, -1), null, 2)}\n`,
    );
    console.log(
      `${kind}: old harness compacted, retained both tail messages, and continued without old history or sibling; captured ${stem}.jsonl and ${contextPath}`,
    );
  } finally {
    await harness?.close(context);
    await repo.close(context);
    await rm(root, { recursive: true, force: true });
  }
}
